mapper.select:
SELECT COUNT(*) FROM (select DATA_DATE from TRM_BRUSH_SCORE where  DATA_DATE between  concat(#{month,jdbcType=VARCHAR},'-01') and concat(#{month,jdbcType=VARCHAR},'-31')

   and PLO_NUM = #{ploNum,jdbcType=VARCHAR}

 group by DATA_DATE)

select A.*,rownum rank from ( select a.PLO_NUM,a.total,nvl(b.right_num,0) right_num,nvl(round(b.right_num/a.total,4),0) right_rate,c.answer_days,d.weak_point1,d.weak_point2,d.weak_point3 from (select plo_num,count(1) as total from TRM_BRUSH_SCORE where DATA_DATE between #{begDate,jdbcType=VARCHAR} and #{endDate,jdbcType=VARCHAR} group by plo_num) a left join (select plo_num,count(1) as right_num from TRM_BRUSH_SCORE where DATA_DATE between #{begDate,jdbcType=VARCHAR} and #{endDate,jdbcType=VARCHAR} and PASS_FLAG=1 group by plo_num) b on (a.PLO_NUM = b.PLO_NUM) left join (select PLO_NUM,count(1) as answer_days from (select plo_num,DATA_DATE from TRM_BRUSH_SCORE where DATA_DATE between #{begDate,jdbcType=VARCHAR} and #{endDate,jdbcType=VARCHAR} group by plo_num,DATA_DATE) group by PLO_NUM) c on (a.PLO_NUM = c.PLO_NUM) left join ( select PLO_NUM,max( CASE rank WHEN 1 THEN concat(CATEGORY,'|'||num) ELSE '' END ) weak_point1,max( CASE rank WHEN 2 THEN concat(CATEGORY,'|'||num) ELSE '' END ) weak_point2,max( CASE rank WHEN 3 THEN concat(CATEGORY,'|'||num) ELSE '' END ) weak_point3 FROM (select PLO_NUM,nvl(t2.CATEGORY,'未分类') CATEGORY,count(1) as num,row_number() over(partition by PLO_NUM order by count(1) desc) rank from (select QUES_CODE,PLO_NUM from TRM_BRUSH_SCORE where DATA_DATE between #{begDate,jdbcType=VARCHAR} and #{endDate,jdbcType=VARCHAR} and PASS_FLAG=0 ) t1 left join (select QUES_CODE,CATEGORY from TRM_QUES_BANK) t2 on (t1.QUES_CODE= t2.QUES_CODE) group by PLO_NUM,CATEGORY order by num desc) group by PLO_NUM ) d on (a.PLO_NUM = d.PLO_NUM)
order by ${orderBy}
) A

select A.*,rownum rank from ( select a.dept_num,a.dept_group,a.total,nvl(b.right_num,0) right_num,nvl(round(b.right_num/a.total,4),0) right_rate,c.HUM_ACT,d.weak_point1,d.weak_point2,d.weak_point3 from (select dept_num,dept_group,count(1) as total from TRM_BRUSH_SCORE where DATA_DATE between #{begDate,jdbcType=VARCHAR} and #{endDate,jdbcType=VARCHAR} group by dept_num,dept_group) a left join (select dept_group,count(1) as right_num from TRM_BRUSH_SCORE where DATA_DATE between #{begDate,jdbcType=VARCHAR} and #{endDate,jdbcType=VARCHAR} and PASS_FLAG=1 group by dept_group) b on (a.dept_group = b.dept_group) left join (select DEPT_GROUP,count(1) as HUM_ACT from (select DEPT_GROUP,plo_num from TRM_BRUSH_SCORE where DATA_DATE between #{begDate,jdbcType=VARCHAR} and #{endDate,jdbcType=VARCHAR} group by dept_group,plo_num) group by DEPT_GROUP) c on (a.DEPT_GROUP = c.DEPT_GROUP) left join ( select DEPT_GROUP,max( CASE rank WHEN 1 THEN concat(CATEGORY,'|'||num) ELSE '' END ) weak_point1,max( CASE rank WHEN 2 THEN concat(CATEGORY,'|'||num) ELSE '' END ) weak_point2,max( CASE rank WHEN 3 THEN concat(CATEGORY,'|'||num) ELSE '' END ) weak_point3 FROM (select DEPT_GROUP,nvl(t2.CATEGORY,'未分类') CATEGORY,count(1) as num,row_number() over(partition by DEPT_GROUP order by count(1) desc) rank from (select QUES_CODE,DEPT_GROUP from TRM_BRUSH_SCORE where DATA_DATE between #{begDate,jdbcType=VARCHAR} and #{endDate,jdbcType=VARCHAR} and PASS_FLAG=0 ) t1 left join (select QUES_CODE,CATEGORY from TRM_QUES_BANK) t2 on (t1.QUES_CODE= t2.QUES_CODE) group by DEPT_GROUP,CATEGORY order by num desc) group by DEPT_GROUP ) d on (a.DEPT_GROUP = d.DEPT_GROUP)
order by ${orderBy}
) A

select A.*,rownum rank from ( select a.dept_num,a.total,nvl(b.right_num,0) right_num,round(b.right_num/a.total,4) right_rate,c.HUM_ACT,d.weak_point1,d.weak_point2,d.weak_point3 from (select dept_num,count(1) as total from TRM_BRUSH_SCORE where DATA_DATE between #{begDate,jdbcType=VARCHAR} and #{endDate,jdbcType=VARCHAR} group by dept_num) a left join (select dept_num,count(1) as right_num from TRM_BRUSH_SCORE where DATA_DATE between #{begDate,jdbcType=VARCHAR} and #{endDate,jdbcType=VARCHAR} and PASS_FLAG=1 group by dept_num) b on (a.dept_num = b.dept_num) left join (select dept_num,count(1) as HUM_ACT from (select dept_num,plo_num from TRM_BRUSH_SCORE where DATA_DATE between #{begDate,jdbcType=VARCHAR} and #{endDate,jdbcType=VARCHAR} group by dept_num,plo_num) group by dept_num) c on (a.dept_num = c.dept_num) left join ( select dept_num,max( CASE rank WHEN 1 THEN concat(CATEGORY,'|'||num) ELSE '' END ) weak_point1,max( CASE rank WHEN 2 THEN concat(CATEGORY,'|'||num) ELSE '' END ) weak_point2,max( CASE rank WHEN 3 THEN concat(CATEGORY,'|'||num) ELSE '' END ) weak_point3 FROM (select dept_num,nvl(t2.CATEGORY,'未分类') CATEGORY,count(1) as num,row_number() over(partition by dept_num order by count(1) desc) rank from (select QUES_CODE,dept_num from TRM_BRUSH_SCORE where DATA_DATE between #{begDate,jdbcType=VARCHAR} and #{endDate,jdbcType=VARCHAR} and PASS_FLAG=0 ) t1 left join (select QUES_CODE,CATEGORY from TRM_QUES_BANK) t2 on (t1.QUES_CODE= t2.QUES_CODE) group by dept_num,CATEGORY order by num desc) group by dept_num ) d on (a.dept_num = d.dept_num)
order by ${orderBy}
) A
